using System;using System.IO;using System.Linq;using System.Drawing;using System.ComponentModel;using System.Collections.Generic;using System.Windows.Forms;
namespace CircuitoStudio {
public sealed class BreakerSelectionForm:Form {
Project project;Circuit circuit;string file;List<BreakerRating> items;DataGridView grid;TextBox details;ComboBox poles,metric;CheckBox compatibleOnly;Label note;public bool Changed{get;private set;}
public BreakerSelectionForm(Project p,Circuit c,string library){project=p;circuit=c;file=library;items=File.Exists(file)?BreakerSelection.Import(file):new List<BreakerRating>();Text="Disjuntores — tensão, polos e Icu/Icn";Size=new Size(1180,700);MinimumSize=new Size(1000,600);Font=new Font("Segoe UI",10);StartPosition=FormStartPosition.CenterParent;var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=140,Padding=new Padding(10),BackColor=Color.FromArgb(225,238,245)};Add(top,"Importar CSV",Import);Add(top,"Modelo vazio CSV",Template);Add(top,"Aplicar selecionado",Apply);Add(top,"Pré-selecionar para avaliar backup",ApplyForStudy);Add(top,"Remover vínculo",Remove);top.Controls.Add(new Label{Text="Configuração exigida",AutoSize=true,Margin=new Padding(8,8,3,0)});poles=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=105};foreach(PoleLayout value in Enum.GetValues(typeof(PoleLayout)))poles.Items.Add(BreakerSelection.PoleName(value));top.Controls.Add(poles);metric=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=75};foreach(BreakingMetric value in Enum.GetValues(typeof(BreakingMetric)))metric.Items.Add(value);top.Controls.Add(metric);compatibleOnly=new CheckBox{Text="Mostrar apenas comparações nominais atendidas",AutoSize=true};top.SetFlowBreak(metric,true);top.Controls.Add(compatibleOnly);note=new Label{Dock=DockStyle.Top,Height=70,Padding=new Padding(10)};details=new TextBox{Dock=DockStyle.Bottom,Height=240,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BackColor=Color.White};grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.DisplayedCells,BackgroundColor=Color.White};grid.SelectionChanged+=delegate{var value=Current();details.Text=value==null?"Nenhuma opção. Importe dados rastreáveis; não há catálogo OEM fornecido.":value.Detail;};Controls.Add(grid);Controls.Add(details);Controls.Add(note);Controls.Add(top);var snapshot=c.Protection.BreakerSnapshot;poles.SelectedIndex=snapshot==null?(c.Phases==PhaseMode.Trifasico?(int)PoleLayout.ThreePole:(int)PoleLayout.OnePoleNeutral):(int)snapshot.RequiredPoles;metric.SelectedIndex=snapshot==null?0:(int)snapshot.RequiredMetric;poles.SelectedIndexChanged+=delegate{RefreshRows();};metric.SelectedIndexChanged+=delegate{RefreshRows();};compatibleOnly.CheckedChanged+=delegate{RefreshRows();};RefreshRows();}
void Add(FlowLayoutPanel panel,string label,Action action){var b=new Button{Text=label,AutoSize=true};b.Click+=delegate{try{action();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Disjuntores",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};panel.Controls.Add(b);}
BreakerEvaluation Current(){return grid.CurrentRow==null?null:grid.CurrentRow.DataBoundItem as BreakerEvaluation;}
void RefreshRows(){var context=Engineering.Analyze(project).For(circuit);if(context==null)throw new InvalidDataException("Circuito fora do projeto.");var results=items.Select(x=>BreakerSelection.Evaluate(project,context,x,(PoleLayout)poles.SelectedIndex,(BreakingMetric)metric.SelectedIndex)).ToList();if(compatibleOnly.Checked)results=results.Where(x=>x.Status=="Atende comparações nominais").ToList();grid.DataSource=new BindingList<BreakerEvaluation>(results);foreach(string name in new[]{"VoltageV","RatedA","CapacityKA"})if(grid.Columns.Contains(name))grid.Columns[name].DefaultCellStyle.Format="0.###";note.Text=circuit.Id+"; "+circuit.Voltage+" V; "+project.Frequency+" Hz; "+results.Count+" de "+items.Count+" registros. AC; confirme a configuração de polos exigida.\r\nIcu/Icn e tensão são comparados na condição exata da ficha. Curto usado: nominal aproximado. A seleção exige revisão de ambiente, curvas, coordenação e Ik máximo.";}
void Import(){using(var dialog=new OpenFileDialog{Filter="CSV|*.csv"})if(dialog.ShowDialog(this)==DialogResult.OK){var rows=BreakerSelection.Import(dialog.FileName);BreakerSelection.Export(rows,file);items=rows;RefreshRows();}}
void Template(){using(var dialog=new SaveFileDialog{Filter="CSV|*.csv",FileName="modelo-disjuntores.csv"})if(dialog.ShowDialog(this)==DialogResult.OK){if(String.Equals(Path.GetFullPath(dialog.FileName),Path.GetFullPath(file),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Use outro nome para preservar a biblioteca.");BreakerSelection.Export(new BreakerRating[0],dialog.FileName);}}
void ApplyForStudy(){var row=Current();if(row==null)return;BreakerSelection.ApplyForCoordinationStudy(project,circuit,row.Rating,(PoleLayout)poles.SelectedIndex,(BreakingMetric)metric.SelectedIndex);Changed=true;DialogResult=DialogResult.OK;Close();}
void Apply(){var row=Current();if(row==null)return;BreakerSelection.Apply(project,circuit,row.Rating,(PoleLayout)poles.SelectedIndex,(BreakingMetric)metric.SelectedIndex);Changed=true;DialogResult=DialogResult.OK;Close();}
void Remove(){if(circuit.Protection.BreakerSnapshot==null)return;circuit.Protection.BreakerSnapshot=null;Changed=true;DialogResult=DialogResult.OK;Close();}
}
partial class Studio{void ConfigureBreakerSelection(){if(circuit==null)throw new InvalidOperationException("Selecione um circuito.");using(var form=new BreakerSelectionForm(project,circuit,Path.Combine(userData,"disjuntores-condicoes.csv")))if(form.ShowDialog(this)==DialogResult.OK&&form.Changed){Change();tabs.SelectedTab=studyPage;}}}
}
